def transform(grid):
    h,w=len(grid),len(grid[0]); out=[row[:] for row in grid]
    # Stamp the L-shaped 3/5 motif with its top-left 3 aligned to each 8.
    offsets=[(0,0,3),(0,1,5),(0,2,3),(1,1,5),(1,2,3),(2,2,3)]
    for r in range(h):
        for c in range(w):
            if grid[r][c]==8:
                for dr,dc,color in offsets:
                    rr,cc=r+dr,c+dc
                    if 0<=rr<h and 0<=cc<w:
                        out[rr][cc]=color
    return out

